<script lang="ts">
 import QRCode from 'qrcode'; let url='';let svg='';let mode='qr';let shortUrl='';let error='';let working=false;let copied=false;let copyError='';
 async function qr(v:string){url=v;if(v&&mode==='qr')svg=await QRCode.toString(v,{type:'svg',margin:2});else svg=''}
 async function shorten(){working=true;error='';shortUrl='';copied=false;copyError='';try{const r=await fetch('/api/shorten',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url})});const isJson=r.headers.get('content-type')?.includes('application/json');const d=isJson?await r.json():null;if(!r.ok)throw Error(d?.error??'Servis pemendek belum tersedia. Semak binding SHORT_URLS di Cloudflare Pages.');shortUrl=d.shortUrl}catch(e){error=e instanceof Error?e.message:'Tidak dapat pendekkan pautan.'}finally{working=false}}
 async function copyShortLink(){if(!shortUrl)return;copyError='';try{await navigator.clipboard.writeText(shortUrl);copied=true;setTimeout(()=>copied=false,2000)}catch{copied=false;copyError='Tidak dapat menyalin secara automatik. Sila salin pautan secara manual.'}}
 async function download(format:'png'|'svg'){if(!url.trim()||!svg)return;const content=format==='svg'?svg:await QRCode.toDataURL(url.trim(),{width:1600,margin:2});const href=format==='svg'?URL.createObjectURL(new Blob([content],{type:'image/svg+xml'})):content;const link=document.createElement('a');link.href=href;link.download=`qora-qr.${format}`;link.click();if(format==='svg')URL.revokeObjectURL(href)}
</script>
<main><header><a href="/">qora</a><nav><button>about</button><button>settings</button></nav></header><section><h1>{mode==='qr'?'QR untuk pautan anda.':'Pendekkan pautan anda.'}</h1><p>{mode==='qr'?'tampal satu pautan, kemudian muat turun QR.':'buat pautan pendek tanpa ubah QR asal anda.'}</p><div class="entry"><span>⌁</span><input value={url} on:input={e=>qr(e.currentTarget.value)} placeholder="paste the link here"/>{#if mode==='shorten'}<button class="go" on:click={shorten}>{working?'…':'→'}</button>{/if}</div><div class="tools"><div><button on:click={()=>{mode='qr';qr(url)}} class:active={mode==='qr'}>✦ QR</button><button on:click={()=>{mode='shorten';svg=''}} class:active={mode==='shorten'}>↗ short</button></div><button class="paste" on:click={()=>navigator.clipboard.readText().then(qr)}>paste</button></div>{#if svg}<div class="result"><div class="qr">{@html svg}</div><div class="downloads"><button on:click={()=>download('png')}>↓ PNG</button><button on:click={()=>download('svg')}>↓ SVG</button></div></div>{/if}{#if shortUrl}<button type="button" class="short-link" on:click={copyShortLink} aria-label="Salin pautan pendek" title="Klik untuk salin pautan"><span>{shortUrl}</span><span class="copy-state" aria-live="polite">{copied?'✓ Disalin!':'⧉ Salin'}</span></button>{/if}{#if copyError}<em>{copyError}</em>{/if}{#if error}<em>{error}</em>{/if}<small class="notice">QR terus ke pautan asal · short link ialah servis berasingan</small></section></main>
<style>
  *{box-sizing:border-box} main{height:100dvh;overflow:hidden;background:#fff;color:#171717}
  header{height:50px;display:flex;align-items:center;justify-content:space-between;width:min(1040px,92%);margin:auto;font:600 13px ui-monospace,SFMono-Regular,monospace} header a{color:#171717;text-decoration:none;font-weight:800;transition:opacity .15s ease} header a:hover{opacity:.55} header nav{display:flex;gap:14px} header button{border:0;background:transparent;color:#888;font:inherit;cursor:pointer;transition:color .15s ease} header button:hover{color:#171717}
  section{width:min(610px,88%);height:calc(100dvh - 50px);margin:auto;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:14px 0 42px;text-align:center;transform:translateY(-12px)} h1{margin:0;font:700 clamp(2rem,5vw,3.2rem)/1 ui-monospace,SFMono-Regular,monospace;letter-spacing:-.08em} p{margin:12px 0 22px;color:#777;font:14px/1.5 ui-monospace,SFMono-Regular,monospace}
  .entry{display:flex;align-items:center;width:100%;height:52px;border:1px solid #222;border-radius:12px;padding:0 14px;box-shadow:0 2px 0 #eee}.entry span{color:#999;font-size:20px}.entry input{flex:1;min-width:0;height:100%;border:0;outline:0;padding:0 12px;background:transparent;font:14px ui-monospace,SFMono-Regular,monospace}.go{border:0;background:#171717;color:#fff;border-radius:8px;width:32px;height:32px;font-size:18px}
  .tools{display:flex;justify-content:space-between;width:100%;margin-top:7px}.tools div{display:flex;border:1px solid #ddd;border-radius:10px;overflow:hidden}.tools button{border:0;border-right:1px solid #ddd;padding:9px 12px;background:#fff;color:#666;font:600 13px ui-monospace,SFMono-Regular,monospace;cursor:pointer;transition:background .15s ease,color .15s ease,transform .15s ease}.tools button:hover{background:#eee;color:#171717}.tools button:active,.downloads button:active{transform:scale(.96)}.tools button:last-child{border:0}.tools .active,.tools .active:hover{background:#171717;color:#fff}.tools .paste{border:1px solid #ddd;border-radius:10px}
  .result{margin-top:22px}.qr{width:200px;padding:14px;border:1px solid #ddd;border-radius:14px}.qr :global(svg){display:block;width:100%;height:auto;aspect-ratio:1}.downloads{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:10px}.downloads button{height:36px;border:1px solid #171717;border-radius:8px;background:#171717;color:#fff;font:700 12px ui-monospace,SFMono-Regular,monospace;cursor:pointer;transition:opacity .15s ease,transform .15s ease}.downloads button:last-child{background:#fff;color:#171717}.downloads button:hover{opacity:.7}
  .short-link{display:flex;align-items:center;justify-content:space-between;gap:12px;max-width:100%;width:100%;margin-top:20px;padding:14px;border:1px solid #ddd;border-radius:10px;background:#f8f8f8;color:#171717;text-align:left;font:600 14px ui-monospace,SFMono-Regular,monospace;cursor:pointer;transition:border-color .15s ease,background .15s ease}.short-link:hover,.short-link:focus-visible{border-color:#171717;background:#f0f0f0}.short-link>span:first-child{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.copy-state{white-space:nowrap;font-size:12px;color:#555}em{margin-top:16px;color:#b22;font:13px ui-monospace,SFMono-Regular,monospace}.notice{margin-top:14px;color:#aaa;font:11px ui-monospace,SFMono-Regular,monospace}@media(max-width:600px){section{padding:12px 0 28px;transform:translateY(-8px)}h1{font-size:2rem}.result{margin-top:18px}.qr{width:160px}.notice{margin-top:12px}}
</style>
